[metadata] {"type": "text", "file": {"filePath": "/app/task/tests/test.patch", "content": "diff --git a/packages/widgets/Specs/VoxelInspector/__tests__/VoxelInspectorViewModelSpec.js b/packages/widgets/Specs/VoxelInspector/__tests__/VoxelInspectorViewModelSpec.js\nnew file mode 100644\nindex 0000000000..b2b7a01580\n--- /dev/null\n+++ b/packages/widgets/Specs/VoxelInspector/__tests__/VoxelInspectorViewModelSpec.js\n@@ -0,0 +1,457 @@\n+import {\n+  Cartesian3,\n+  HeadingPitchRoll,\n+  Matrix3,\n+  Matrix4,\n+  VoxelShapeType,\n+} from \"@cesium/engine\";\n+import { VoxelInspectorViewModel } from \"../../../index.js\";\n+\n+// Regression #12521 (\"Cylinder bounds are mislabeled in Voxel Inspector\", fixed by PR #12522):\n+// packages/widgets/Source/VoxelInspector/VoxelInspectorViewModel.js defines the cylinder\n+// \"Bounds\"/\"Clipping\" editor properties (boundsCylinderMax/MinHeight, boundsCylinderMax/MinAngle,\n+// and their clipping* counterparts) via getBoundSetter(\"maxBounds\"|\"minBounds\"|\n+// \"maxClippingBounds\"|\"minClippingBounds\", component), where `component` is one of \"x\"/\"y\"/\"z\"\n+// into the primitive's Cartesian3 bound. VoxelCylinderShape's own (unchanged-by-this-bug)\n+// convention -- confirmed directly in VoxelCylinderShape's constructor, which reads\n+// this._minimumAngle from DefaultMinBounds.y and this._minimumHeight from DefaultMinBounds.z --\n+// is x=radius, y=angle, z=height. Prior to the fix (introduced by #12432), the Height properties\n+// were wired to the \"y\" (angle) component and the Angle properties were wired to the \"z\" (height)\n+// component: dragging the Inspector's \"Height\" field actually changed the cylinder's angular\n+// extent, and dragging \"Angle\" actually changed its height, exactly as reported (\"play with the\n+// height and angle sliders... they actually control the other parameter\"; see\n+// /app/.harbor_assets/bug_screenshot_1.png, where the \"Max Height\" field displays 3.14159...\n+// (pi, the angle range) and /app/.harbor_assets/bug_screenshot_2.png, where dragging \"Max Height\"\n+// visibly carves an angular wedge out of the cylinder).\n+//\n+// This spec drives VoxelInspectorViewModel directly (no Scene/WebGL/DOM needed -- the whole\n+// class only ever calls `scene.requestRender()`, never anything else on `scene`, and the\n+// `voxelPrimitive` setter only needs `.shape`, `.modelMatrix`, `.maxBounds`/`.minBounds`/\n+// `.maxClippingBounds`/`.minClippingBounds` (real Cartesian3 instances, since getBoundSetter\n+// calls `.clone()` on them), and `.customShaderCompilationEvent.addEventListener`), with a\n+// lightweight mock \"voxel primitive\" carrying real, independently distinguishable radius/angle/\n+// height values on each axis.\n+//\n+// Coverage is deliberately symmetric: every one of the 8 cylinder Height/Angle properties (Max\n+// and Min, in both the \"Bounds\" and \"Clipping\" panels) is exercised in BOTH directions -- reading\n+// the property off a fresh primitive, and writing through the property back onto the primitive.\n+// The underlying bug is 8 independent one-line component swaps (4 \"Bounds\" addProperty blocks, 4\n+// \"Clipping\" blocks), each wiring both a getter and a setter to a component letter, so a fix that\n+// only touches some of those blocks (e.g. \"Bounds\" but not \"Clipping\", or Max but not Min), or\n+// that updates a block's getter without its setter (or vice versa), is a genuine, still-broken\n+// regression -- not merely a stylistic difference -- and must fail here.\n+describe(\"Widgets/VoxelInspector/VoxelInspectorViewModel\", function () {\n+  const scene = {\n+    requestRender: function () {},\n+  };\n+\n+  // Distinct per-axis sentinel values so a component mix-up is unambiguous: x (radius), y\n+  // (angle), z (height) never share a value.\n+  const RADIUS_MAX = 7.0;\n+  const RADIUS_MIN = 0.0;\n+  const ANGLE_MAX = Math.PI;\n+  const ANGLE_MIN = -Math.PI / 2;\n+  const HEIGHT_MAX = 11.0;\n+  const HEIGHT_MIN = -13.0;\n+\n+  function makeMockPrimitive() {\n+    return {\n+      shape: VoxelShapeType.CYLINDER,\n+      modelMatrix: Matrix4.clone(Matrix4.IDENTITY, new Matrix4()),\n+      maxBounds: new Cartesian3(RADIUS_MAX, ANGLE_MAX, HEIGHT_MAX),\n+      minBounds: new Cartesian3(RADIUS_MIN, ANGLE_MIN, HEIGHT_MIN),\n+      maxClippingBounds: new Cartesian3(RADIUS_MAX, ANGLE_MAX, HEIGHT_MAX),\n+      minClippingBounds: new Cartesian3(RADIUS_MIN, ANGLE_MIN, HEIGHT_MIN),\n+      // Read unconditionally by the \"shaderString\" property's getPrimitiveFunction, which runs\n+      // for every registered getPrimitiveFunction whenever `voxelPrimitive` is assigned (not\n+      // just when the shader-related properties are actually touched).\n+      customShader: {\n+        fragmentShaderText: \"void fragmentVoxel(inout czm_voxelProperty voxel) {}\",\n+      },\n+      customShaderCompilationEvent: {\n+        addEventListener: function () {\n+          return function () {};\n+        },\n+      },\n+    };\n+  }\n+\n+  // A real (if tiny) pub/sub, standing in for Cesium's actual Event class: addEventListener\n+  // records a subscriber and returns a genuine unsubscribe function; raise() invokes whichever\n+  // subscribers are still registered. Used where a test needs to observe an OUTCOME (does a\n+  // listener still fire after cleanup?) rather than asserting that some specific function\n+  // reference was called -- the latter would pin one implementation of \"removal\" among several\n+  // equally-correct ones (e.g. filtering an array vs. a Set vs. a linked list of subscribers).\n+  function makeEventBus() {\n+    let subscribers = [];\n+    return {\n+      addEventListener: function (callback) {\n+        subscribers.push(callback);\n+        return function () {\n+          subscribers = subscribers.filter(function (s) {\n+            return s !== callback;\n+          });\n+        };\n+      },\n+      raise: function (error) {\n+        subscribers.slice().forEach(function (s) {\n+          s(error);\n+        });\n+      },\n+    };\n+  }\n+\n+  let viewModel;\n+  let mockPrimitive;\n+\n+  beforeEach(function () {\n+    viewModel = new VoxelInspectorViewModel(scene);\n+    mockPrimitive = makeMockPrimitive();\n+    viewModel.voxelPrimitive = mockPrimitive;\n+  });\n+\n+  // --- f2p: the reported regression, \"Bounds\" panel -----------------------------------------\n+\n+  it(\"reads boundsCylinderMaxHeight from the height (z) component of maxBounds, not the angle (y) component (regression #12521)\", function () {\n+    expect(viewModel.boundsCylinderMaxHeight).toEqual(mockPrimitive.maxBounds.z);\n+    expect(viewModel.boundsCylinderMaxHeight).not.toEqual(mockPrimitive.maxBounds.y);\n+  });\n+\n+  it(\"setting boundsCylinderMaxHeight writes the height (z) component of maxBounds, leaving the angle (y) component unchanged (regression #12521)\", function () {\n+    const originalAngle = mockPrimitive.maxBounds.y;\n+    viewModel.boundsCylinderMaxHeight = 99.0;\n+    expect(mockPrimitive.maxBounds.z).toEqual(99.0);\n+    expect(mockPrimitive.maxBounds.y).toEqual(originalAngle);\n+  });\n+\n+  it(\"reads boundsCylinderMinHeight from the height (z) component of minBounds, not the angle (y) component (regression #12521)\", function () {\n+    expect(viewModel.boundsCylinderMinHeight).toEqual(mockPrimitive.minBounds.z);\n+    expect(viewModel.boundsCylinderMinHeight).not.toEqual(mockPrimitive.minBounds.y);\n+  });\n+\n+  it(\"setting boundsCylinderMinHeight writes the height (z) component of minBounds, leaving the angle (y) component unchanged (regression #12521)\", function () {\n+    const originalAngle = mockPrimitive.minBounds.y;\n+    viewModel.boundsCylinderMinHeight = -99.0;\n+    expect(mockPrimitive.minBounds.z).toEqual(-99.0);\n+    expect(mockPrimitive.minBounds.y).toEqual(originalAngle);\n+  });\n+\n+  it(\"reads boundsCylinderMaxAngle from the angle (y) component of maxBounds, not the height (z) component (regression #12521)\", function () {\n+    expect(viewModel.boundsCylinderMaxAngle).toEqual(mockPrimitive.maxBounds.y);\n+    expect(viewModel.boundsCylinderMaxAngle).not.toEqual(mockPrimitive.maxBounds.z);\n+  });\n+\n+  it(\"setting boundsCylinderMaxAngle writes the angle (y) component of maxBounds, leaving the height (z) component unchanged (regression #12521)\", function () {\n+    const originalHeight = mockPrimitive.maxBounds.z;\n+    viewModel.boundsCylinderMaxAngle = 2.5;\n+    expect(mockPrimitive.maxBounds.y).toEqual(2.5);\n+    expect(mockPrimitive.maxBounds.z).toEqual(originalHeight);\n+  });\n+\n+  it(\"reads boundsCylinderMinAngle from the angle (y) component of minBounds, not the height (z) component (regression #12521)\", function () {\n+    expect(viewModel.boundsCylinderMinAngle).toEqual(mockPrimitive.minBounds.y);\n+    expect(viewModel.boundsCylinderMinAngle).not.toEqual(mockPrimitive.minBounds.z);\n+  });\n+\n+  it(\"setting boundsCylinderMinAngle writes the angle (y) component of minBounds, leaving the height (z) component unchanged (regression #12521)\", function () {\n+    const originalHeight = mockPrimitive.minBounds.z;\n+    viewModel.boundsCylinderMinAngle = -1.23;\n+    expect(mockPrimitive.minBounds.y).toEqual(-1.23);\n+    expect(mockPrimitive.minBounds.z).toEqual(originalHeight);\n+  });\n+\n+  // --- f2p: the reported regression, \"Clipping\" panel ---------------------------------------\n+\n+  it(\"reads clippingCylinderMaxHeight from the height (z) component of maxClippingBounds, not the angle (y) component (regression #12521)\", function () {\n+    expect(viewModel.clippingCylinderMaxHeight).toEqual(\n+      mockPrimitive.maxClippingBounds.z,\n+    );\n+    expect(viewModel.clippingCylinderMaxHeight).not.toEqual(\n+      mockPrimitive.maxClippingBounds.y,\n+    );\n+  });\n+\n+  it(\"setting clippingCylinderMaxHeight writes the height (z) component of maxClippingBounds, leaving the angle (y) component unchanged (regression #12521)\", function () {\n+    const originalAngle = mockPrimitive.maxClippingBounds.y;\n+    viewModel.clippingCylinderMaxHeight = 88.0;\n+    expect(mockPrimitive.maxClippingBounds.z).toEqual(88.0);\n+    expect(mockPrimitive.maxClippingBounds.y).toEqual(originalAngle);\n+  });\n+\n+  it(\"reads clippingCylinderMinHeight from the height (z) component of minClippingBounds, not the angle (y) component (regression #12521)\", function () {\n+    expect(viewModel.clippingCylinderMinHeight).toEqual(\n+      mockPrimitive.minClippingBounds.z,\n+    );\n+    expect(viewModel.clippingCylinderMinHeight).not.toEqual(\n+      mockPrimitive.minClippingBounds.y,\n+    );\n+  });\n+\n+  it(\"setting clippingCylinderMinHeight writes the height (z) component of minClippingBounds, leaving the angle (y) component unchanged (regression #12521)\", function () {\n+    const originalAngle = mockPrimitive.minClippingBounds.y;\n+    viewModel.clippingCylinderMinHeight = -77.0;\n+    expect(mockPrimitive.minClippingBounds.z).toEqual(-77.0);\n+    expect(mockPrimitive.minClippingBounds.y).toEqual(originalAngle);\n+  });\n+\n+  it(\"reads clippingCylinderMaxAngle from the angle (y) component of maxClippingBounds, not the height (z) component (regression #12521)\", function () {\n+    expect(viewModel.clippingCylinderMaxAngle).toEqual(\n+      mockPrimitive.maxClippingBounds.y,\n+    );\n+    expect(viewModel.clippingCylinderMaxAngle).not.toEqual(\n+      mockPrimitive.maxClippingBounds.z,\n+    );\n+  });\n+\n+  it(\"setting clippingCylinderMaxAngle writes the angle (y) component of maxClippingBounds, leaving the height (z) component unchanged (regression #12521)\", function () {\n+    const originalHeight = mockPrimitive.maxClippingBounds.z;\n+    viewModel.clippingCylinderMaxAngle = 2.5;\n+    expect(mockPrimitive.maxClippingBounds.y).toEqual(2.5);\n+    expect(mockPrimitive.maxClippingBounds.z).toEqual(originalHeight);\n+  });\n+\n+  it(\"reads clippingCylinderMinAngle from the angle (y) component of minClippingBounds, not the height (z) component (regression #12521)\", function () {\n+    expect(viewModel.clippingCylinderMinAngle).toEqual(\n+      mockPrimitive.minClippingBounds.y,\n+    );\n+    expect(viewModel.clippingCylinderMinAngle).not.toEqual(\n+      mockPrimitive.minClippingBounds.z,\n+    );\n+  });\n+\n+  it(\"setting clippingCylinderMinAngle writes the angle (y) component of minClippingBounds, leaving the height (z) component unchanged (regression #12521)\", function () {\n+    const originalHeight = mockPrimitive.minClippingBounds.z;\n+    viewModel.clippingCylinderMinAngle = -0.5;\n+    expect(mockPrimitive.minClippingBounds.y).toEqual(-0.5);\n+    expect(mockPrimitive.minClippingBounds.z).toEqual(originalHeight);\n+  });\n+\n+  // --- p2p: adjacent code that must NOT be touched by the fix -------------------------------\n+\n+  it(\"still reads boundsCylinderMaxRadius from the radius (x) component of maxBounds (unaffected by the height/angle fix)\", function () {\n+    expect(viewModel.boundsCylinderMaxRadius).toEqual(mockPrimitive.maxBounds.x);\n+  });\n+\n+  it(\"still reads clippingCylinderMinRadius from the radius (x) component of minClippingBounds (unaffected by the height/angle fix)\", function () {\n+    expect(viewModel.clippingCylinderMinRadius).toEqual(\n+      mockPrimitive.minClippingBounds.x,\n+    );\n+  });\n+\n+  it(\"still writes boundsBoxMaxY to the box shape's maxBounds.y component (a distinct, box-only property sharing the same getBoundSetter('maxBounds','y') helper; must not be swapped by a fix scoped to cylinder-only properties)\", function () {\n+    viewModel.boundsBoxMaxY = 42.0;\n+    expect(mockPrimitive.maxBounds.y).toEqual(42.0);\n+  });\n+\n+  it(\"still reads boundsEllipsoidMaxHeight from the ellipsoid shape's maxBounds.z component (ellipsoid already used z for height before this bug; must remain unaffected by the cylinder fix)\", function () {\n+    expect(viewModel.boundsEllipsoidMaxHeight).toEqual(mockPrimitive.maxBounds.z);\n+  });\n+\n+  it(\"still updates the primitive's modelMatrix translation when translationX changes (unrelated ViewModel functionality, unaffected by the bounds/clipping fix)\", function () {\n+    viewModel.translationX = 5.0;\n+    const translation = Matrix4.getTranslation(\n+      mockPrimitive.modelMatrix,\n+      new Cartesian3(),\n+    );\n+    expect(translation.x).toEqual(5.0);\n+  });\n+\n+  // --- f2p: boolean/number coercion in the shared addProperty() setter ----------------------\n+  //\n+  // Every boolean-valued property (show, depthTest, disableUpdate, debugDraw, jitter,\n+  // nearestSampling, ...) is defined through the same addProperty() helper, which converts an\n+  // incoming numeric 0/1 (as arrives from e.g. a checkbox bound through knockout's\n+  // valueUpdate/checkedValue plumbing) to a boolean before storing it. A fix must repair the\n+  // shared helper itself, not special-case any one property name -- so coverage below exercises\n+  // more than one boolean property.\n+\n+  it(\"setting a boolean property to the numeric value 1 turns it on (show)\", function () {\n+    viewModel.show = 0;\n+    viewModel.show = 1;\n+    expect(viewModel.show).toBe(true);\n+  });\n+\n+  it(\"setting a boolean property to the numeric value 0 turns it off (show)\", function () {\n+    viewModel.show = 1;\n+    viewModel.show = 0;\n+    expect(viewModel.show).toBe(false);\n+  });\n+\n+  it(\"setting a different boolean property to the numeric value 1 turns it on (jitter), confirming the fix is not special-cased to a single property name\", function () {\n+    viewModel.jitter = 0;\n+    viewModel.jitter = 1;\n+    expect(viewModel.jitter).toBe(true);\n+  });\n+\n+  it(\"still stores a plain numeric property (screenSpaceError) as the number itself, not coerced to a boolean, when set via a number (unaffected by the boolean-coercion fix)\", function () {\n+    viewModel.screenSpaceError = 8;\n+    expect(viewModel.screenSpaceError).toBe(8);\n+  });\n+\n+  // --- f2p: shape-type detection (shapeIsCylinder / shapeIsEllipsoid) -----------------------\n+  //\n+  // shapeIsBox/shapeIsEllipsoid/shapeIsCylinder each compare the primitive's `.shape` against\n+  // one VoxelShapeType enum member. shapeIsCylinder and shapeIsEllipsoid must each report true\n+  // for their own shape type and false for the other.\n+\n+  it(\"shapeIsCylinder is true and shapeIsEllipsoid is false when the primitive's shape is CYLINDER\", function () {\n+    // mockPrimitive (assigned in beforeEach) already has shape CYLINDER.\n+    expect(viewModel.shapeIsCylinder).toBe(true);\n+    expect(viewModel.shapeIsEllipsoid).toBe(false);\n+  });\n+\n+  it(\"shapeIsEllipsoid is true and shapeIsCylinder is false when the primitive's shape is ELLIPSOID\", function () {\n+    const ellipsoidPrimitive = makeMockPrimitive();\n+    ellipsoidPrimitive.shape = VoxelShapeType.ELLIPSOID;\n+    viewModel.voxelPrimitive = ellipsoidPrimitive;\n+    expect(viewModel.shapeIsEllipsoid).toBe(true);\n+    expect(viewModel.shapeIsCylinder).toBe(false);\n+  });\n+\n+  it(\"still reports shapeIsBox correctly, with shapeIsCylinder and shapeIsEllipsoid both false, for a BOX-shaped primitive (unaffected by the cylinder/ellipsoid fix)\", function () {\n+    const boxPrimitive = makeMockPrimitive();\n+    boxPrimitive.shape = VoxelShapeType.BOX;\n+    viewModel.voxelPrimitive = boxPrimitive;\n+    expect(viewModel.shapeIsBox).toBe(true);\n+    expect(viewModel.shapeIsCylinder).toBe(false);\n+    expect(viewModel.shapeIsEllipsoid).toBe(false);\n+  });\n+\n+  // --- f2p: Transform panel rotation (angleX/angleY/angleZ -> heading/pitch/roll) ------------\n+  //\n+  // setModelMatrix() builds a HeadingPitchRoll from angleX/angleY/angleZ (heading/pitch/roll\n+  // respectively) and turns it into the primitive's modelMatrix rotation. Scale defaults to\n+  // (1,1,1) and translation to (0,0,0), so with those left untouched the upper 3x3 of\n+  // modelMatrix (Matrix4.getMatrix3) is exactly the HeadingPitchRoll rotation matrix -- computed\n+  // here independently via Cesium's own Matrix3.fromHeadingPitchRoll, never by re-reading the\n+  // ViewModel's internals.\n+\n+  it(\"the model matrix's rotation reflects angleX/angleY/angleZ as heading/pitch/roll respectively\", function () {\n+    viewModel.angleX = 0.3;\n+    viewModel.angleY = 0.5;\n+    viewModel.angleZ = 0.7;\n+    const expectedRotation = Matrix3.fromHeadingPitchRoll(\n+      new HeadingPitchRoll(0.3, 0.5, 0.7),\n+      new Matrix3(),\n+    );\n+    const actualRotation = Matrix4.getMatrix3(\n+      mockPrimitive.modelMatrix,\n+      new Matrix3(),\n+    );\n+    expect(Matrix3.equalsEpsilon(actualRotation, expectedRotation, 1e-10)).toBe(\n+      true,\n+    );\n+  });\n+\n+  it(\"setting only angleY rotates the model matrix as a pure pitch, not a pure roll (regression risk: pitch/roll cross-wired)\", function () {\n+    viewModel.angleY = 0.8;\n+    const pitchRotation = Matrix3.fromHeadingPitchRoll(\n+      new HeadingPitchRoll(0.0, 0.8, 0.0),\n+      new Matrix3(),\n+    );\n+    const rollRotation = Matrix3.fromHeadingPitchRoll(\n+      new HeadingPitchRoll(0.0, 0.0, 0.8),\n+      new Matrix3(),\n+    );\n+    const actualRotation = Matrix4.getMatrix3(\n+      mockPrimitive.modelMatrix,\n+      new Matrix3(),\n+    );\n+    expect(Matrix3.equalsEpsilon(actualRotation, pitchRotation, 1e-10)).toBe(\n+      true,\n+    );\n+    expect(Matrix3.equalsEpsilon(actualRotation, rollRotation, 1e-10)).toBe(\n+      false,\n+    );\n+  });\n+\n+  it(\"setting only angleZ rotates the model matrix as a pure roll, not a pure pitch (regression risk: pitch/roll cross-wired)\", function () {\n+    viewModel.angleZ = 0.8;\n+    const rollRotation = Matrix3.fromHeadingPitchRoll(\n+      new HeadingPitchRoll(0.0, 0.0, 0.8),\n+      new Matrix3(),\n+    );\n+    const pitchRotation = Matrix3.fromHeadingPitchRoll(\n+      new HeadingPitchRoll(0.0, 0.8, 0.0),\n+      new Matrix3(),\n+    );\n+    const actualRotation = Matrix4.getMatrix3(\n+      mockPrimitive.modelMatrix,\n+      new Matrix3(),\n+    );\n+    expect(Matrix3.equalsEpsilon(actualRotation, rollRotation, 1e-10)).toBe(\n+      true,\n+    );\n+    expect(Matrix3.equalsEpsilon(actualRotation, pitchRotation, 1e-10)).toBe(\n+      false,\n+    );\n+  });\n+\n+  it(\"still rotates the model matrix as a pure heading rotation when only angleX changes (unaffected by the pitch/roll fix)\", function () {\n+    viewModel.angleX = 0.9;\n+    const headingRotation = Matrix3.fromHeadingPitchRoll(\n+      new HeadingPitchRoll(0.9, 0.0, 0.0),\n+      new Matrix3(),\n+    );\n+    const actualRotation = Matrix4.getMatrix3(\n+      mockPrimitive.modelMatrix,\n+      new Matrix3(),\n+    );\n+    expect(Matrix3.equalsEpsilon(actualRotation, headingRotation, 1e-10)).toBe(\n+      true,\n+    );\n+  });\n+\n+  // --- f2p: shader-compilation listener cleanup on primitive swap ---------------------------\n+  //\n+  // Assigning `voxelPrimitive` must remove the PREVIOUS primitive's shader-compilation listener\n+  // before/while attaching the new one, so repeatedly swapping primitives (as happens whenever\n+  // the Inspector is pointed at a different VoxelPrimitive) never accumulates stale listeners.\n+  //\n+  // Each primitive here carries its own real event bus (makeEventBus(), above), so \"was the\n+  // listener removed\" is checked by observing an OUTCOME -- raising the event on the OLD\n+  // primitive's bus after a swap must have no effect on the ViewModel -- rather than by\n+  // asserting that some specific function reference was invoked. Any correct implementation of\n+  // \"stop listening to the old primitive\" passes this, regardless of how it tracks subscriptions\n+  // internally.\n+\n+  it(\"removes the previous primitive's shader-compilation listener when a new voxelPrimitive is assigned\", function () {\n+    const primitiveA = makeMockPrimitive();\n+    primitiveA.customShaderCompilationEvent = makeEventBus();\n+    viewModel.voxelPrimitive = primitiveA;\n+\n+    const primitiveB = makeMockPrimitive();\n+    viewModel.voxelPrimitive = primitiveB;\n+\n+    viewModel.shaderCompilationMessage = \"untouched\";\n+    primitiveA.customShaderCompilationEvent.raise(new Error(\"stale, from A\"));\n+    expect(viewModel.shaderCompilationMessage).toEqual(\"untouched\");\n+  });\n+\n+  it(\"continues removing the immediately-previous primitive's listener on further swaps, not just the first one\", function () {\n+    const primitiveA = makeMockPrimitive();\n+    primitiveA.customShaderCompilationEvent = makeEventBus();\n+    const primitiveB = makeMockPrimitive();\n+    primitiveB.customShaderCompilationEvent = makeEventBus();\n+    const primitiveC = makeMockPrimitive();\n+\n+    viewModel.voxelPrimitive = primitiveA;\n+    viewModel.voxelPrimitive = primitiveB;\n+    viewModel.voxelPrimitive = primitiveC;\n+\n+    viewModel.shaderCompilationMessage = \"untouched\";\n+    primitiveA.customShaderCompilationEvent.raise(new Error(\"stale, from A\"));\n+    primitiveB.customShaderCompilationEvent.raise(new Error(\"stale, from B\"));\n+    expect(viewModel.shaderCompilationMessage).toEqual(\"untouched\");\n+  });\n+\n+  it(\"still invokes the newly-assigned primitive's own shader-compilation callback correctly after a swap (unaffected by the listener-cleanup fix)\", function () {\n+    const primitiveA = makeMockPrimitive();\n+    primitiveA.customShaderCompilationEvent = makeEventBus();\n+    viewModel.voxelPrimitive = primitiveA;\n+\n+    primitiveA.customShaderCompilationEvent.raise(new Error(\"boom\"));\n+    expect(viewModel.shaderCompilationSuccess).toBe(false);\n+    expect(viewModel.shaderCompilationMessage).toEqual(\"boom\");\n+  });\n+});\n", "numLines": 464, "startLine": 1, "totalLines": 464}}

